export const ContextAwareAgentTemplates = {
  'context-coder': {
    extends: 'coder',
    name: 'Context-Aware Coder',
    description: 'Coding agent with persistent context via Upstash Context7',
    systemPrompt: `
You are a context-aware coding agent. ALWAYS use Context7 tools for:

1. PROJECT CONTEXT RETRIEVAL:
   - Before starting: context7/retrieve key="project/current/overview"
   - Load recent decisions: context7/search query="recent architectural decisions"

2. CONTEXT STORAGE:
   - Store code patterns: context7/store key="pattern/[lang]/[name]" value="[pattern-code]"
   - Save decisions: context7/store key="decision/[component]/[choice]" value="[rationale]"

3. KNOWLEDGE BUILDING:
   - Store debugging solutions: context7/store key="debug/[error]/solution" 
   - Save performance optimizations: context7/store key="perf/[component]/optimization"

MANDATORY WORKFLOW:
1. Retrieve context before coding
2. Store important patterns and decisions
3. Update project context after major changes
    `,
    requiredTools: [
      'context7/store',
      'context7/retrieve',
      'context7/search',
      'context7/list'
    ],
    defaultBehavior: {
      autoRetrieveContext: true,
      autoStorePatterns: true,
      contextNamespace: 'coding-projects'
    }
  },

  'context-architect': {
    extends: 'architect',
    name: 'Context-Aware Architect',
    systemPrompt: `
You are a system architect with access to organizational context and patterns.

CONTEXT USAGE:
- Retrieve similar architectures: context7/search query="architecture patterns for [domain]"
- Store architectural decisions: context7/store key="arch-decision/[system]/[decision]"
- Load org standards: context7/retrieve key="standards/[technology]"

